import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from sankey ----
type SankeyCategory = 'fossil' | 'nuclear' | 'renewable' | 'conversion' | 'end-use' | 'loss';

interface SankeyNodeDatum {
  id: string;
  category: SankeyCategory;
}

interface SankeyLinkDatum {
  source: string;
  target: string;
  value: number;
}

/** Synthetic national energy balance: primary sources -> conversion -> end use, in TWh. */
const sankeyNodes: SankeyNodeDatum[] = [
  { id: 'Coal', category: 'fossil' },
  { id: 'Natural Gas', category: 'fossil' },
  { id: 'Oil', category: 'fossil' },
  { id: 'Nuclear', category: 'nuclear' },
  { id: 'Wind', category: 'renewable' },
  { id: 'Solar', category: 'renewable' },
  { id: 'Hydro', category: 'renewable' },
  { id: 'Electricity', category: 'conversion' },
  { id: 'Heat', category: 'conversion' },
  { id: 'Transport Fuel', category: 'conversion' },
  { id: 'Residential', category: 'end-use' },
  { id: 'Commercial', category: 'end-use' },
  { id: 'Industrial', category: 'end-use' },
  { id: 'Transport', category: 'end-use' },
  { id: 'Losses', category: 'loss' }
];

const sankeyLinks: SankeyLinkDatum[] = [
  { source: 'Coal', target: 'Electricity', value: 120 },
  { source: 'Natural Gas', target: 'Electricity', value: 180 },
  { source: 'Natural Gas', target: 'Heat', value: 90 },
  { source: 'Nuclear', target: 'Electricity', value: 150 },
  { source: 'Wind', target: 'Electricity', value: 95 },
  { source: 'Solar', target: 'Electricity', value: 40 },
  { source: 'Hydro', target: 'Electricity', value: 35 },
  { source: 'Oil', target: 'Transport Fuel', value: 210 },
  { source: 'Oil', target: 'Heat', value: 30 },
  { source: 'Electricity', target: 'Residential', value: 180 },
  { source: 'Electricity', target: 'Commercial', value: 150 },
  { source: 'Electricity', target: 'Industrial', value: 200 },
  { source: 'Electricity', target: 'Losses', value: 90 },
  { source: 'Heat', target: 'Residential', value: 70 },
  { source: 'Heat', target: 'Commercial', value: 30 },
  { source: 'Heat', target: 'Losses', value: 20 },
  { source: 'Transport Fuel', target: 'Transport', value: 160 },
  { source: 'Transport Fuel', target: 'Losses', value: 50 }
];

const MIN_HEIGHT = 320;
const MAX_HEIGHT = 520;
const HEIGHT_RATIO = 0.55;
const MARGIN_X = 8;
const MARGIN_Y = 10;
const NODE_WIDTH = 12;
const NODE_PADDING = 10;
const LABEL_MIN_WIDTH = 480;

const color = d3
  .scaleOrdinal<SankeyCategory, string>()
  .domain(['fossil', 'nuclear', 'renewable', 'conversion', 'end-use', 'loss'])
  .range([...d3.schemeObservable10.slice(0, 5), 'var(--muted)']);

const format = d3.format(',.0f');

interface LayoutNode {
  id: string;
  category: SankeyCategory;
  value: number;
  x0: number;
  x1: number;
  y0: number;
  y1: number;
}

interface LayoutLink {
  source: string;
  target: string;
  value: number;
  x0: number;
  x1: number;
  y0: number;
  y1: number;
  width: number;
}

/** A flow network: nodes carrying a colour category, and valued links between node ids. */
export type Data = {
  nodes: { id: string; category: SankeyCategory }[];
  links: { source: string; target: string; value: number }[];
};

const DEMO: Data = { nodes: sankeyNodes, links: sankeyLinks };

/** Assigns each node to a column by longest path from a source, then stacks columns by value. */
function layoutSankey({ nodes, links: flows }: Data, width: number, height: number) {
  const outgoing = d3.group(flows, (l) => l.source);
  const incoming = d3.group(flows, (l) => l.target);

  // Longest-path column assignment via Kahn's algorithm.
  const depth = new Map(nodes.map((n) => [n.id, 0]));
  const inDegree = new Map(nodes.map((n) => [n.id, incoming.get(n.id)?.length ?? 0]));
  const queue = nodes.filter((n) => inDegree.get(n.id) === 0).map((n) => n.id);
  while (queue.length) {
    const id = queue.shift()!;
    for (const link of outgoing.get(id) ?? []) {
      depth.set(link.target, Math.max(depth.get(link.target)!, depth.get(id)! + 1));
      inDegree.set(link.target, inDegree.get(link.target)! - 1);
      if (inDegree.get(link.target) === 0) queue.push(link.target);
    }
  }

  const value = new Map(
    nodes.map((n) => {
      const out = d3.sum(outgoing.get(n.id) ?? [], (l) => l.value);
      const inn = d3.sum(incoming.get(n.id) ?? [], (l) => l.value);
      return [n.id, Math.max(out, inn)];
    })
  );

  const maxDepth = d3.max(depth.values()) ?? 0;
  const columns = d3.group(nodes, (n) => depth.get(n.id)!);
  const innerWidth = width - MARGIN_X * 2 - NODE_WIDTH;
  const step = maxDepth > 0 ? innerWidth / maxDepth : 0;
  const plotHeight = height - MARGIN_Y * 2;

  // A single pixel-per-unit scale, sized to fit the most crowded column.
  const scale = d3.min(columns, ([, column]) => {
    const total = d3.sum(column, (n) => value.get(n.id)!);
    return (plotHeight - NODE_PADDING * (column.length - 1)) / total;
  })!;

  const nodesById = new Map<string, LayoutNode>();
  for (const [col, column] of columns) {
    const columnHeight = d3.sum(column, (n) => value.get(n.id)! * scale) + NODE_PADDING * (column.length - 1);
    let y = MARGIN_Y + (plotHeight - columnHeight) / 2;
    const x0 = MARGIN_X + col * step;
    for (const n of column) {
      const h = value.get(n.id)! * scale;
      nodesById.set(n.id, {
        id: n.id,
        category: n.category,
        value: value.get(n.id)!,
        x0,
        x1: x0 + NODE_WIDTH,
        y0: y,
        y1: y + h
      });
      y += h + NODE_PADDING;
    }
  }

  // Slice each node's height among its links, in declaration order, so bands don't overlap.
  const sourceCursor = new Map(nodes.map((n) => [n.id, nodesById.get(n.id)!.y0]));
  const targetCursor = new Map(nodes.map((n) => [n.id, nodesById.get(n.id)!.y0]));
  const links: LayoutLink[] = flows.map((link) => {
    const h = link.value * scale;
    const y0 = sourceCursor.get(link.source)! + h / 2;
    const y1 = targetCursor.get(link.target)! + h / 2;
    sourceCursor.set(link.source, sourceCursor.get(link.source)! + h);
    targetCursor.set(link.target, targetCursor.get(link.target)! + h);
    return {
      ...link,
      x0: nodesById.get(link.source)!.x1,
      x1: nodesById.get(link.target)!.x0,
      y0,
      y1,
      width: Math.max(1, h)
    };
  });

  return { nodes: [...nodesById.values()], links };
}

function linkPath(link: LayoutLink): string {
  const xMid = (link.x0 + link.x1) / 2;
  return `M${link.x0},${link.y0}C${xMid},${link.y0} ${xMid},${link.y1} ${link.x1},${link.y1}`;
}

export default function Sankey({ data = DEMO, width }: { data?: Data; width: number }) {
  const height = Math.min(MAX_HEIGHT, Math.max(MIN_HEIGHT, width * HEIGHT_RATIO));
  const showLabels = width >= LABEL_MIN_WIDTH;

  const { nodes, links } = useMemo(() => layoutSankey(data, width, height), [data, width, height]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Sankey diagram of a national energy balance, from primary sources through conversion to end use"
    >
      <g fillOpacity={0.5}>
        {links.map((link, i) => (
          <path
            key={i}
            d={linkPath(link)}
            fill="none"
            stroke={color(nodes.find((n) => n.id === link.source)!.category)}
            strokeWidth={link.width}
            style={{ mixBlendMode: 'multiply' }}
          >
            <title>{`${link.source} → ${link.target}\n${format(link.value)} TWh`}</title>
          </path>
        ))}
      </g>
      <g stroke="var(--bg)">
        {nodes.map((n) => (
          <rect
            key={n.id}
            x={n.x0}
            y={n.y0}
            width={n.x1 - n.x0}
            height={Math.max(1, n.y1 - n.y0)}
            fill={color(n.category)}
          >
            <title>{`${n.id}\n${format(n.value)} TWh`}</title>
          </rect>
        ))}
      </g>
      {showLabels && (
        <g fontSize={10} fill="var(--text)">
          {nodes.map((n) => {
            const midY = (n.y0 + n.y1) / 2;
            const onLeftHalf = n.x0 < width / 2;
            return (
              <text
                key={n.id}
                x={onLeftHalf ? n.x1 + 6 : n.x0 - 6}
                y={midY}
                dy="0.35em"
                textAnchor={onLeftHalf ? 'start' : 'end'}
              >
                {n.id}
              </text>
            );
          })}
        </g>
      )}
    </svg>
  );
}
